// Known-contracts registry per network (docs/SPEC.md §8), generated by `pnpm known-contracts`.
import { z } from "zod";
import type { Network } from "@guardian402/shared";
import fuji from "../../config/known-contracts.fuji.json" with { type: "json" };
import local from "../../config/known-contracts.local.json" with { type: "json" };
import type { KnownContract } from "./types.ts";

const registrySchema = z.record(
  z.string().regex(/^0x[0-9a-f]{40}$/, "keys must be lowercase addresses"),
  z.object({
    name: z.string().min(1),
    kind: z.enum(["token", "router", "oracle", "vault", "registry", "other"]),
  }),
);

const registries: Record<Network, Record<string, KnownContract>> = {
  fuji: registrySchema.parse(fuji),
  local: registrySchema.parse(local),
};

export function loadKnownContracts(network: Network): Record<string, KnownContract> {
  return registries[network];
}
